48	kj::Array<capnp::word> CapnProtoRowInputFormat::readMessage()
49	{
50	    uint32_t segment_count;
51	    in->readStrict(reinterpret_cast<char*>(&segment_count), sizeof(uint32_t));
52	
53	    // one for segmentCount and one because segmentCount starts from 0
54	    const auto prefix_size = (2 + segment_count) * sizeof(uint32_t);
55	    const auto words_prefix_size = (segment_count + 1) / 2 + 1;
56	    auto prefix = kj::heapArray<capnp::word>(words_prefix_size);
57	    auto prefix_chars = prefix.asChars();
58	    ::memcpy(prefix_chars.begin(), &segment_count, sizeof(uint32_t));
59	
60	    // read size of each segment
61	    for (size_t i = 0; i <= segment_count; ++i)
62	        in->readStrict(prefix_chars.begin() + ((i + 1) * sizeof(uint32_t)), sizeof(uint32_t));
63	
64	    // calculate size of message
65	    const auto expected_words = capnp::expectedSizeInWordsFromPrefix(prefix);
66	    const auto expected_bytes = expected_words * sizeof(capnp::word);
67	    const auto data_size = expected_bytes - prefix_size;
68	    auto msg = kj::heapArray<capnp::word>(expected_words);
69	    auto msg_chars = msg.asChars();
70	
71	    // read full message
72	    ::memcpy(msg_chars.begin(), prefix_chars.begin(), prefix_size);
73	    in->readStrict(msg_chars.begin() + prefix_size, data_size);
74	
75	    return msg;
76	}
